// Group notes rendered by `scripts describe` and the reference generator: the common rules of a
// module or of a receiver type, which belong to no single entry. Source, not generated.
#nullable enable

namespace Scripts.Core;

/// <summary>One module or receiver group with the rules common to its entries.</summary>
public sealed record StdlibGroupNote(string Name, string Kind, string Notes);

public static class StdlibNotes
{
    public static readonly IReadOnlyList<StdlibGroupNote> All =
    [
        new("filesystem", "module", "Common rules: any relative path is resolved by the system relative to the current directory of the process; no normalisation is done by scripts, except that the no-follow paths (`filesystem.get_path_status`, `filesystem.set_owner_no_follow`, `filesystem.make_directory_with_permissions`, `filesystem.remove_directory_tree`, `filesystem.touch`) trim trailing `/` before the no-follow call so a final symbolic link is not followed through the slash; symbolic links are followed by the system unless stated otherwise; system-call errors are translated by the errno table above;\na path containing NUL gives `invalid_path` before any call, except in `filesystem.path_exists`, which returns `false`; all these functions have `deterministic=false` (they depend on the state of the file system); the examples create their data in a temporary directory that they remove.\n\nThe `filesystem` namespace exposes the **nature** of each directory entry (`\"file\"`,`\"directory\"`,`\"symlink\"`,`\"other\"`), obtained for free from the `d_type` of `readdir`. The returned type is the `directory_entry` record (`path`, `kind`;).\n\n`filesystem.list_directory` is the direct listing. `filesystem.walk_directory` is the depth-first traversal and returns a `walk_report` through two records:\n\n| Type | Fields |\n|---|---|\n| `walk_report` | `entries: list<directory_entry>`, `skipped_paths: list<walk_skip>` |\n| `walk_skip` | `path_text: string`, `kind: string` (`\"permission_denied\"`,`\"invalid_encoding\"`,`\"other\"`) |\n\nIt also provides `filesystem.write_file_overwrite_atomically`, an atomic replacement of a file's contents (scratch file in the destination directory, then `rename(2)`), for readers that must never observe a half-written file, and `filesystem.read_file_bounded`, which reads at most a caller-supplied number of bytes and returns `error(too_large)` instead of materializing a whole large file."),
        new("process", "module", "Common rules: **no** execution of `/bin/sh`. Resolution of `program` (the same for `process.request` at launch, `process.run_inherit`, `process.spawn` and `process.find_program_path`): if it contains `/` it is used as is (relative to the current directory if it is not absolute);\notherwise the search is **only** in the entries of `PATH` (empty or relative entries ignored; a regular file with at least one executable bit `0o111`); `PATH` absent or empty → `error(not_found)`. The resolved absolute path is passed to the system.\nDetails (completions): \"executable bit\" = at least one of the `0o111` bits of the mode (links followed); the search reads the **current** `PATH` of the process (so after `environment.set_variable`/`environment.remove_variable`) and keeps the first valid candidate in `PATH` order; a candidate that is not an executable regular file is ignored (with no valid candidate: `not_found`, never `permission_denied`);\nwith a `program` containing `/`, the path is passed as is (made absolute without normalisation), without a prior test, and the launch failure is translated by errno. Table errno → `error.kind`: `ENOENT`, `ENOTDIR` → `not_found`; `EACCES`, `EPERM` → `permission_denied`; `E2BIG`, `ENOEXEC`, `ENOMEM` and any other errno → `other`. The child's `argv[0]` is the absolute path passed to the system.\nAn empty `program`, or a `program`/argument containing NUL → `error(invalid_argument)` before any system call. Children inherit the current environment (including `environment.set_variable/remove`) and the current directory.\nA non-zero exit code **is not** an error; a launch failure is an `error`. Outputs decoded as **strict** UTF-8 **without** BOM detection (U+FEFF kept); invalid bytes → `error(invalid_encoding)` with the program as `subject`. An exit code ≥ 128 is indistinguishable from a death by signal.\nLint: `process.spawn`/`process.request` with a literal program whose basename ∈ {`sh bash dash zsh csh scripts ksh tcsh env xargs busybox python python3 perl ruby node`} emits `SCRIPTS-LINT-0001`; a **computed** (non-literal) program of one of those functions emits `SCRIPTS-LINT-0004` (both warnings).\n**Process groups (S18).** Every captured child — `process.run`, `process.spawn`, `parallel.run_all` and every pipeline stage — is started through `posix_spawn` with `POSIX_SPAWN_SETPGROUP`, so it is in its **own process group** before `exec`: on termination (signal received by scripts, a request deadline, `process.terminate`, scripts exiting for an unwaited child) scripts walks `/proc` deepest-first, then signals the whole group with `killpg(2)`. `process.run_inherit` inherits stdin in both modes, so it keeps scripts's terminal and group; a terminal-generated signal reaches it directly, and on termination it is signalled together with its `/proc`-visible descendants. A captured child is in a background group and must not read the controlling terminal (it would stop with `SIGTTIN`). A descendant that has left the `/proc` parent chain **and** the process group before the signal (a successful `setsid`) is not reached; one that is still in the chain, or still in the group, is reached — and when the child ends on its own, scripts does not hunt the processes it left behind.\nThe module function `process.pipeline_to_file_overwrite` (§7.10) composes several `run_request`s into one pipeline: its stages follow these same resolution, error, output-decoding and process-group rules, and every stage is registered in the run's child table."),
        new("environment", "module", "Common rules: an empty `name`, containing `=` or NUL, or a `value` containing NUL → `error` (`error.subject` = the name provided); names are case-sensitive; modifications (`set`/`remove`) concern the scripts process and are inherited by children launched afterwards."),
        new("system", "module", "Common rules: these functions read kernel or user-database facts; `system.effective_user_id`/`effective_group_id` are `geteuid(2)`/`getegid(2)`, and `system.user_id`/`group_id` consult the live NSS user/group database (so they are not deterministic). An unknown name is `not_found` with the name as `subject`; a name containing NUL is `invalid_argument`; a name too large for the 1 MiB lookup buffer is `other`. `system.get_information`, `system.user_name` and `system.cpu_count` are likewise host-dependent."),
        new("io", "module", "The standard modules are **intrinsic namespaces**: `environment`, `io`, `process`, `json`,\n`filesystem`, `parallel`, `system`, `time`, `encoding`, `random` and `csv` are reserved and always available, without any import. Their functions are\ncalled `namespace.name(...)`. There is **no `std:` namespace**: an `import \"std:…\"` path is rejected\nwith `SCRIPTS-MODULE-0005` (\"standard modules are intrinsic\"). An intrinsic namespace has neither public\nconstants nor user functions: its functions are native (resolved by the catalog)."),
        new("json", "module", "The standard modules are **intrinsic namespaces**: `environment`, `io`, `process`, `json`,\n`filesystem`, `parallel`, `system`, `time`, `encoding`, `random` and `csv` are reserved and always available, without any import. Their functions are\ncalled `namespace.name(...)`. There is **no `std:` namespace**: an `import \"std:…\"` path is rejected\nwith `SCRIPTS-MODULE-0005` (\"standard modules are intrinsic\"). An intrinsic namespace has neither public\nconstants nor user functions: its functions are native (resolved by the catalog)."),
        new("encoding", "module", "The `encoding` namespace converts **text** to and from standard base64, hexadecimal, and RFC 3986 percent-encoding (`url_encode`/`url_decode`). A `string` is UTF-8 text and bytes are never values: encoders take the UTF-8 bytes of the text, and the `*_decode` functions return a string only when the decoded bytes are **strict** UTF-8 (no BOM detection, U+FEFF kept). Malformed input is `invalid_argument`; bytes that are not valid UTF-8 are `invalid_encoding`. These functions are pure and deterministic."),
        new("random", "module", "The `random` namespace draws from the operating system's **CSPRNG** (`System.Security.Cryptography.RandomNumberGenerator`): `bytes_hex`/`bytes_base64` return encoded random bytes, and `integer_below` is an unbiased 64-bit rejection-sampled integer. `byte_count` is `0..1048576` and `upper_bound` is `1..9223372036854775807`; a value outside its range is `invalid_argument`, and a zero count returns `ok(\"\")`. The results are not reproducible: every entry is `deterministic=false`."),
        new("csv", "module", "The `csv` namespace provides minimal RFC 4180 CSV parsing and encoding (`parse`, `parse_row`, `encode_row`, `encode`). Fields are separated by `,`, quoted with `\"`, escaped with `\"\"`, and multi-line quoted fields are supported. Malformed quotes or unexpected characters return `error(invalid_argument)`. Encoded rows are joined with `\\n`; a lone empty field is written `\"\"`. `csv.parse(csv.encode(rows))` returns `rows` when every row has at least one field, and `csv.parse_row(csv.encode_row(fields))` returns `fields` for every row, including the row with no field. All functions are pure and deterministic."),
        new("parallel", "module", "The `parallel` namespace runs work **in bounded concurrency** while keeping the guarantees of the language: no `async`, no exposed thread, a synchronous `result`. Results are always returned in the **input order** (`transform`, `run_all`) or in the **lexicographic pre-order order** of `filesystem.walk_directory` (`walk_directory`, root excluded), whatever the completion order.\n\n`worker_count` is an **argument**: outside `1..256`, the call returns `error(kind=invalid_worker_count)` — **never silently clamped**. `worker_count == 1` runs **sequentially on the calling thread** and produces the same **results** in input order as any larger bound **when the call succeeds**. The **first failure** interrupts execution: exactly **one** `error`, **no partial list**; the still-living children of `run_all` are **killed** with their still-attached descendants before returning. Under concurrency the first failure **observed** may differ from the input order (a later request can fail before an earlier one completes), so the failure returned is not guaranteed identical across `worker_count` values. The 2^28 output limit is fatal (`SCRIPTS-RUNTIME-0013`, like `process.run`) when it is observed before an abort. `items` is **frozen** on entry (value semantics,).\n\n> Note (memory model): `mapper` and `visit` capture by reference and may run on several threads. An **inline lambda** is an **expression**, so it can neither assign (`+=`) nor use `?`; a **direct mutating method** (`append`, `remove_key`) on a mutable variable captured from outside is a **static error** (`SCRIPTS-TYPE-0063`), because the workers share it. A **nested function** — declared inside another function — can capture a `mutable` of its enclosing function and mutate it, and a **function value** can hold such a function; neither can be proven side-effect free, so a worker may neither call one nor be one: `SCRIPTS-TYPE-0066` (a top-level function cannot see a script `mutable`, `SCRIPTS-TYPE-0007`, and stays allowed). Capturing immutable or constant values is always safe."),
        new("path", "type", "There is no module function left in this namespace; the operations are pure and manipulate text only (UTF-16 units): no disk access. Every operation except `path.normalized()` keeps the text as written (`.`/`..` are ordinary components); `normalized()` is the one explicit normal form, and it never touches the disk. A component is a maximal sequence of characters other than `/`; repeated or trailing `/` are ignored when determining the last component.\n\nThere is **no `path` namespace** in an earlier revision: `/` is the only join, and every lexical operation is a receiver method of §7.5.1 (`base_name`, `extension`, `parent`, `to_string`, `is_absolute`, `normalized`, `file_stem`, `with_extension`, `matches_glob`).\n\nA `path` is text (UTF-16 units); these methods are the receiver API of `path`, pure and deterministic. The signatures below name the **receiver type**, not a namespace: `path` is an ordinary identifier in an earlier revision and a path value is written `p\"…\"`, `(…).to_path()` or `a / b`."),
        new("string", "type", "A `string` is a sequence of Unicode scalars; all text comparisons are **ordinal** (without culture, without normalisation). The methods never modify the receiver (immutable values); they are pure and deterministic."),
        new("list", "type", "Value semantics: a list assigned or passed is logically copied; `append` only modifies the receiver variable. Lists are homogeneous, indexed from 0; `list[i]` out of bounds is fatal (`SCRIPTS-RUNTIME-0004`, writing `SCRIPTS-RUNTIME-0005`).\nCallback methods (`filter`, `transform`, `fold`, `sorted_by`, `any_match`, `all_match`, `count`, `find_first`) call the lambda **in element order**, once per iterated element; `any_match`/`all_match`/`find_first` **short-circuit** at the first decisive element, `count` walks all elements; each call counts as 1 for the call depth (10000); a lambda cannot use `?` or assign."),
        new("map", "type", "`K` ∈ { `string`, `integer`, `path`, `boolean` }. Iteration (`keys`, `values`) follows the **insertion order**; the equality of two maps is that of the sets of pairs (order-insensitive). An absent `m[k]` is fatal (`SCRIPTS-RUNTIME-0006`); `m[k] = v` inserts at the end or replaces keeping the position."),
        new("json_value", "type", "A `json_value` is **opaque** (like `process_handle`): it is not `match`ed and not interpolated, it is read through its accessors. `kind()` returns the JSON nature; `as_*()` returns the scalar value when the type matches, otherwise `error(not_encodable)`."),
        new("file_lock", "type", "A `file_lock` is **opaque**: it has no fields, no JSON form, and cannot be `match`ed, interpolated or compared. It is created by `filesystem.acquire_file_lock` and released by `file_lock.release`; release is idempotent (a second call returns `ok(())`), and the descriptor is closed by the process when scripts exits. Use `process.defer` to release deterministically."),
        new("process_result", "type", "A `process_result` is the result of `process.run`/`process.wait_for_process` (fields `exit_code`, `standard_output`, `standard_error`, `program`; `program` is the program string as passed to the call). A non-zero exit code **is not** a launch error (the function returns `ok`); the following method allows turning it into a typed failure to propagate it."),
    ];
}
